// Lektionen 31–36 (Offenbarungsreihenfolge, Kairoer Chronologie)
window.LEKTIONEN6 = [
// ───────────────────────── Lektion 31: Al-Qiyāma ─────────────────────────
{
sure: 75, offb: 31, name: "Al-Qiyāma", arab: "سُورَةُ الْقِيَامَةِ", de: "Die Auferstehung", verse: 40, ort: "Mekka",
zeit: "Frühmekkanisch – Antwort auf die Kernfrage Mekkas: „Sollen zerfallene Knochen wirklich wieder leben?“",
kurz: "Die Sure, die der Auferstehung ihren Namen gibt – und sie gegen den Spott Mekkas verteidigt. Auf die höhnische Frage „Wann ist dieser Tag der Auferstehung?“ antwortet Allah mit einem Detail, das jeden Zweifel beschämt: „Meint der Mensch, Wir würden seine Knochen nicht zusammenfügen? Doch – Wir sind fähig, (sogar) seine Fingerspitzen zurechtzuformen.“ Nicht nur die Knochen: die Fingerkuppen mit ihren Linien, bei jedem Menschen einzigartig. Dazu schwört Allah bei der sich selbst tadelnden Seele (nafs lawwāma) – deinem inneren Zeugen, dass es Verantwortung gibt. Mittendrin eine persönliche Szene: Der Prophet ﷺ bewegte hastig die Lippen, um die Offenbarung nicht zu vergessen – Allah beruhigt ihn: „Uns obliegt sein Sammeln und sein Vortrag.“ Dann die zwei Gesichter des Endes: strahlende Gesichter, „die zu ihrem Herrn schauen“ – und die Sterbeszene dessen, der „weder die Wahrheit annahm noch betete“.",
schluessel: {arab: "بَلَىٰ قَادِرِينَ عَلَىٰ أَن نُّسَوِّيَ بَنَانَهُ", ueb: "Doch! Wir sind fähig, (sogar) seine Fingerspitzen zurechtzuformen.", ref: "75:4"},
kontext: ["Der Streitpunkt Nummer eins zwischen dem Propheten ﷺ und Mekka war nicht Gottes Existenz (die bejahten sie), sondern die Auferstehung: ʿAdī ibn Rabīʿa u. a. fragten höhnisch nach Terminen und zerriebenen Knochen. Die Sure nimmt diese Fragen auf (75:3, 75:6) und dreht sie um: Das Problem ist nicht Allahs Können, sondern des Menschen Wollen – „Nein, der Mensch will (nur) vor sich hin weiter sündigen“ (75:5): Der Zweifel an der Abrechnung ist oft Wunschdenken der Begierde, nicht Ergebnis des Denkens.",
"Die Verse 16–19 haben einen eigenen, gesicherten Anlass: Ibn ʿAbbās berichtet, der Prophet ﷺ pflegte bei der Offenbarung Zunge und Lippen eilig zu bewegen, aus Angst, etwas zu vergessen. Da kam herab: „Bewege deine Zunge nicht damit, um dich damit zu übereilen. Uns obliegt sein Sammeln und sein Vortrag; wenn Wir ihn vortragen, dann folge seinem Vortrag. Hierauf obliegt Uns seine Erläuterung.“ Danach hörte der Prophet ﷺ ruhig zu und rezitierte anschließend (Sahih al-Buchari, Nr. 5; Sahih Muslim, Nr. 448). Dieselbe Garantie wie 87:6 (Lektion 8) – der Koran ist von Allah gesammelt, vorgetragen und erläutert.",
"Berühmt ist die Sure auch für einen ʿAqīda-Kernvers: „(Manche) Gesichter werden an jenem Tag strahlen, zu ihrem Herrn schauen (ilā rabbihā nāẓira)“ (75:22–23). Ahl as-Sunna lehren daraus mit den Hadithen: Die Gläubigen werden ihren Herrn im Jenseits wirklich sehen – die höchste aller Freuden."],
asbab: [
 {text: "Ibn ʿAbbās zu 75:16–19: Der Prophet ﷺ bewegte eilig die Lippen, um die Offenbarung festzuhalten – da sicherte Allah ihm Sammlung, Vortrag und Erläuterung des Korans zu.", quelle: "Sahih al-Buchari, Nr. 5; Sahih Muslim, Nr. 448"}
],
begriffe: [
 {arab: "النَّفْس اللَّوَّامَة", tr: "an-nafs al-lawwāma", wurzel: "l-w-m", erkl: "„Die sich selbst tadelnde Seele“ – die mittlere der drei Seelenstufen (vgl. Lektion 10): das Gewissen, das nach der Tat anklopft. Allah schwört bei ihr neben dem Tag der Auferstehung: Dein innerer Tadel ist der Vorbote des äußeren Gerichts – wer ihn hat, lebt; wer ihn zum Schweigen bringt, stirbt innerlich."},
 {arab: "بَنَان", tr: "banān", wurzel: "b-n-n", erkl: "Fingerspitzen/Fingerkuppen – die Antwort auf den Knochen-Spott: Nicht nur grobe Rekonstruktion, sondern Feinarbeit bis in die Fingerlinien. Dass gerade die Fingerkuppe jeden Menschen eindeutig identifiziert, macht den Vers für heutige Leser nur noch schärfer."},
 {arab: "سُدًى", tr: "sudā", wurzel: "s-d-y", erkl: "„Sich selbst überlassen, ziellos“ – 75:36: „Meint der Mensch, er würde sudā gelassen?“ Wie ein Kamel, das unbeaufsichtigt weidet. Das stärkste Kurzargument für die Auferstehung: Ein Schöpfer, der Verstand, Gewissen und Offenbarung gibt, lässt nicht ungeprüft weiden."},
 {arab: "نَاظِرَة", tr: "nāẓira", wurzel: "n-ẓ-r", erkl: "„schauend“ – 75:23: Gesichter, „zu ihrem Herrn schauend“. Mit den Hadithen (unten) Grundlage der Sunna-Lehre vom Sehen Allahs (ruʾya) im Jenseits – ohne Umfassen und ohne ‚Wie', wie bei allen Eigenschaften."},
 {arab: "التَفَّتِ السَّاقُ بِالسَّاق", tr: "iltaffati s-sāqu bi-s-sāq", wurzel: "s-w-q", erkl: "„Und (wenn) sich das Bein ums Bein windet“ (75:29) – das Sterbebild: die Beine, die nicht mehr tragen, Todeskampf und Aufbruch; gedeutet auch als: die Not des Diesseits trifft auf die Not des Jenseits. „Zu deinem Herrn ist an jenem Tag das Treiben (al-masāq).“"},
 {arab: "أَوْلَىٰ لَكَ فَأَوْلَىٰ", tr: "aulā laka fa-aulā", wurzel: "w-l-y", erkl: "„Wehe dir, ja wehe! Und abermals: Wehe dir, ja wehe!“ (75:34–35) – vierfache Drohformel gegen den, der „weder die Wahrheit annahm noch betete, sondern leugnete und sich abkehrte und dann prahlend (yatamaṭṭā) zu seiner Familie stolzierte“. Der stolzierende Gang nach dem Abweisen der Wahrheit – ein zeitloses Porträt."}
],
tafsir: [
 {vers: "Verse 1–15", text: "Doppelschwur (Tag der Auferstehung, tadelnde Seele), dann die Fingerspitzen-Antwort und die Entlarvung: Der Mensch fragt nach dem Termin, weil er „vor sich hin weiter sündigen will“ (li-yafdschura amāmahu – dieselbe fudschūr-Wurzel wie in Lektion 26!). Dann der Tag selbst: geblendeter Blick, verfinsterter Mond, Sonne und Mond vereint – und der Mensch ruft: „Wohin fliehen?“ – „Nein! Keine Zuflucht! Zu deinem Herrn ist an jenem Tag der Ankunftsort.“ Höhepunkt 75:14–15: „Vielmehr ist der Mensch gegen sich selbst Einsicht (baṣīra) – auch wenn er seine Entschuldigungen vorbringt.“ Ibn Kathīr: Du kennst dich; die Ausreden täuschen höchstens andere. As-Saʿdī: Der Vers macht jede Selbstrechtfertigung zur Doppel-Lüge – nach außen und gegen das eigene Wissen."},
 {vers: "Verse 16–19", text: "Die Einschaltung über den Koran-Empfang (Anlass oben): vier Zusagen Allahs – Sammlung (dschamʿ) im Herzen des Propheten ﷺ, Vortrag (qurʾān), Folge-Rezitation, Erläuterung (bayān). Al-Qurṭubī: Hier liegt die Wurzel der gesamten Koranbewahrung – Allah selbst ist der Garant (vgl. 15:9); die spätere Sammlung unter Abū Bakr und ʿUthmān vollzog äußerlich nach, was innerlich längst gesichert war. Lernregel daraus (von den Gelehrten gezogen): Erst zuhören, dann sprechen – Hast beim Wissenserwerb nimmt dem Wissen die Ordnung."},
 {vers: "Verse 20–30", text: "„Keineswegs! Vielmehr liebt ihr das Eilige (al-ʿādschila) und lasst das Jenseits“ – die Diagnose hinter allem Jenseits-Zweifel: Gegenwarts-Sucht. Dann der große Kontrast: „(Manche) Gesichter werden an jenem Tag strahlend sein (nāḍira), zu ihrem Herrn schauen (nāẓira)“ – das Wortspiel nāḍira/nāẓira: Das Strahlen kommt vom Schauen. Der Prophet ﷺ: „Ihr werdet euren Herrn sehen, wie ihr diesen (Voll-)Mond seht; ihr drängt euch bei seinem Anblick nicht“ – und empfahl deshalb, Fadschr und ʿAṣr zu hüten (Sahih al-Buchari, Nr. 554; Sahih Muslim, Nr. 633). Daneben die anderen Gesichter: finster, „die ahnen, dass ihnen das Rückgratbrechende widerfährt“. Dann die Sterbeszene: „Nein! Wenn sie die Schlüsselbeine erreicht (die Seele) und gesagt wird: Wer ist ein Heiler/Beschwörer (man rāq)? und er merkt, dass es der Abschied ist …“ – die Sure holt die Auferstehungsfrage vom Spekulieren ins Sterbezimmer: Dort entscheidet sich, was du wirklich geglaubt hast."},
 {vers: "Verse 31–40", text: "Das Porträt des Verweigerers („nicht die Wahrheit angenommen, nicht gebetet, geleugnet, abgekehrt, dann prahlend davonstolziert“) mit dem vierfachen aulā laka. Dann das Schlussargument in Frageform: „Meint der Mensch, dass er sich selbst überlassen wird? War er nicht ein Tropfen ergossenen Samens, dann ein Anhängsel (ʿalaqa – vgl. Lektion 1!), dann hat Er erschaffen und zurechtgeformt und daraus beide Geschlechter gemacht? Hat dieser (Gott) nicht die Macht, die Toten wieder lebendig zu machen?“ – Vom Propheten ﷺ ist überliefert, hier zu antworten: „Subḥānaka fa-balā – Gepriesen bist Du, doch!“ (Sunan Abū Dāwūd, Nr. 884; die Kette gilt als gestützt; vgl. die Antwort-Sunna aus Lektion 28). Wer die Erst-Erschaffung erlebt hat – sich selbst –, trägt den Beweis der Zweit-Erschaffung am eigenen Leib."}
],
ahadith: [
 {text: "Ibn ʿAbbās über die eilig bewegten Lippen des Propheten ﷺ und die Herabsendung von 75:16–19 – „so hörte er danach zu, und wenn Dschibrīl gegangen war, rezitierte er es, wie er es rezitiert hatte“.", quelle: "Sahih al-Buchari, Nr. 5; Sahih Muslim, Nr. 448"},
 {text: "„Ihr werdet euren Herrn (am Jüngsten Tag) sehen, wie ihr diesen Mond seht – ihr drängt euch bei seinem Anblick nicht. Wenn ihr es vermögt, dass euch kein Gebet vor Sonnenaufgang und vor Sonnenuntergang entgeht, dann tut es.“", quelle: "Sahih al-Buchari, Nr. 554; Sahih Muslim, Nr. 633"},
 {text: "„Allah freut sich über die Reue Seines Dieners mehr als einer von euch, der sein (verloren geglaubtes) Reittier wiederfindet …“ – die Tür für die lawwāma-Seele: Selbsttadel soll in Tauba münden, nicht in Verzweiflung.", quelle: "Sahih al-Buchari, Nr. 6309; Sahih Muslim, Nr. 2747"}
],
hanafi: null,
umsetzung: [
 "Pflege deine nafs lawwāma: Nimm dir abends zwei Minuten Selbst-Abrechnung (muḥāsaba) – EIN Tadel, EINE Tauba, EIN Vorsatz. Der innere Richter ist Gnade; nutze ihn, bevor der äußere tagt.",
 "Hüte Fadschr und ʿAṣr konsequent – der Prophet ﷺ verknüpft genau diese beiden Gebete mit dem Schauen zu Allah (Buchari 554). Das ist der konkreteste ‚Investitionstipp' dieser Sure.",
 "Übernimm die Lernregel aus 75:16–19: Beim Wissen erst ganz zuhören/lesen, dann wiedergeben – keine Hast, keine halben Zitate. Auch fürs Koran-Auswendiglernen: Qualität vor Tempo.",
 "Entlarve das ʿādschila-Muster (75:20) bei dir: Wo wählst du systematisch das Sofortige gegen das Bessere (Scrollen statt Schlaf, Konsum statt Sadaqa)? Eine Sofort-Gewohnheit diese Woche gegen eine Jenseits-Gewohnheit tauschen."
]
},

// ───────────────────────── Lektion 32: Al-Humaza ─────────────────────────
{
sure: 104, offb: 32, name: "Al-Humaza", arab: "سُورَةُ الْهُمَزَةِ", de: "Der Stichler", verse: 9, ort: "Mekka",
zeit: "Frühmekkanisch – gegen die Lästerer und Geldzähler der mekkanischen Oberschicht",
kurz: "Neun Verse gegen eine Doppel-Sünde, die bis heute Hand in Hand geht: Menschen kleinmachen und Geld großmachen. „Wehe jedem Stichler und Nörgler (humaza lumaza), der Besitz sammelt und ihn (immer wieder) zählt – er meint, sein Besitz mache ihn unsterblich.“ Die Antwort des Himmels ist das härteste Feuerbild des Korans: al-ḥuṭama, „die Zermalmende“, Allahs entfachtes Feuer, „das über die Herzen emporsteigt“ – es trifft zuerst das Organ, aus dem Hochmut und Spott kamen. Die Sure ist der Spiegel für jede Gesellschaft, in der Status durch Herabsetzung anderer und Sicherheit durch Kontostand gesucht wird – und sie sagt: Beides ist dieselbe Krankheit.",
schluessel: {arab: "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ ۝ الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ", ueb: "Wehe jedem Stichler und Nörgler, der Besitz sammelt und ihn immer wieder zählt!", ref: "104:1–2"},
kontext: ["Als Anlass nennen die Tafsir-Werke verschiedene mekkanische Großkaufleute, die den Propheten ﷺ und die armen Muslime systematisch verspotteten – al-Achnas ibn Scharīq, al-Walīd ibn al-Muġīra, Umayya ibn Chalaf; kein Bericht ist sahih gesichert, und viele Gelehrte sagen: bewusst – der Wortlaut gilt JEDEM humaza lumaza. Das Suren-Paar aus Spott und Geld passte auf die halbe Oberschicht Mekkas.",
"Humaza und lumaza sind Intensivformen: Der eine sticht mit Gesten und hinter dem Rücken, der andere nörgelt ins Gesicht – die Sprachgelehrten verteilen die Nuancen verschieden; zusammen decken sie das ganze Spektrum ab: Lästern, Spotten, Augenrollen, Nachäffen, abfällige Spitznamen, heute: Hetz-Kommentare und Häme-Kultur. Der Koran behandelt das nicht als Kavaliersdelikt, sondern stellt es neben den Götzendienst des Geldes.",
"Die Logik der Verbindung: Wer Menschen kleinmacht, braucht etwas, das IHN groß macht – meist den Besitz. „Er zählt ihn immer wieder“ (ʿaddadahu): das Ritual der Selbstvergewisserung. „Er meint, sein Besitz mache ihn unsterblich“ – niemand sagt das laut, aber jeder, der für das Konto die Seele opfert, lebt es. Dieselbe Diagnose wie 102 (Lektion 16), hier verschärft um die soziale Waffe des Spotts."],
asbab: ["Die Tafsir-Werke nennen mehrere mekkanische Spötter als mögliche Anlasspersonen (al-Achnas ibn Scharīq, al-Walīd ibn al-Muġīra, Umayya ibn Chalaf u. a.); keiner der Berichte ist sahih gesichert. Nach der Regel „Maßgeblich ist der allgemeine Wortlaut“ gilt die Sure jedem, der ihr Profil erfüllt."],
begriffe: [
 {arab: "هُمَزَة", tr: "humaza", wurzel: "h-m-z", erkl: "Der Stichler – von hamaza: stoßen, stechen (daher auch die Zuflucht vor den hamazāt der Satane, 23:97). Der, der Menschen mit Worten, Gesten und Blicken ‚absticht' – besonders hinter ihrem Rücken."},
 {arab: "لُمَزَة", tr: "lumaza", wurzel: "l-m-z", erkl: "Der Nörgler/Herabsetzer – lamaza: mit Worten oder Winken herabsetzen (vgl. 49:11: „lā talmizū anfusakum – macht einander nicht herab“). Die Intensivform: einer, bei dem das Herabsetzen zur zweiten Natur geworden ist."},
 {arab: "عَدَّدَهُ", tr: "ʿaddadahu", wurzel: "ʿ-d-d", erkl: "„Er zählt ihn immer wieder“ – die Verdopplungsform: zwanghaftes Nachzählen, Bilanz-Scrollen, Depot-Checken als Beruhigungsritual. Zählen ersetzt Vertrauen: Wer bei Allah nichts angelegt hat, muss unten ständig nachzählen."},
 {arab: "أَخْلَدَهُ", tr: "achladahu", wurzel: "ch-l-d", erkl: "„(dass sein Besitz) ihn unsterblich macht“ – chulūd: Ewigkeit. Der stille Irrglaube hinter aller Geldfixierung: Sicherheit = Unsterblichkeit light. Der Koran reserviert chulūd für das Jenseits – in beide Richtungen."},
 {arab: "الْحُطَمَة", tr: "al-ḥuṭama", wurzel: "ḥ-ṭ-m", erkl: "„Die Zermalmende“ – von ḥaṭama: zerbrechen, zermalmen. Ein Eigenname der Hölle, nur hier: Das Feuer, das zermalmt, wie der Spötter Ehren zermalmte. Strafe in der Form der Tat."},
 {arab: "تَطَّلِعُ عَلَى الْأَفْئِدَة", tr: "taṭṭaliʿu ʿalā l-afʾida", wurzel: "ṭ-l-ʿ / f-ʾ-d", erkl: "„(Das Feuer,) das über die Herzen emporsteigt“ – fuʾād: das brennende Innere des Herzens. Es trifft zuerst den Sitz von Hochmut, Neid und Spott – die präziseste ‚Anatomie' einer Korans-Strafe."},
 {arab: "مُؤْصَدَة / عَمَد مُمَدَّدَة", tr: "muʾṣada / ʿamad mumaddada", wurzel: "w-ṣ-d / m-d-d", erkl: "„Über ihnen verschlossen – in langgestreckten Säulen“: das Feuer als verriegelter Raum. Der, der andere sozial ‚einschloss' (ausgrenzte), wird eingeschlossen. Die Mufassirūn: kein Entkommen, keine Tür, keine Zuschauer mehr für seine Show."}
],
tafsir: [
 {vers: "Verse 1–3", text: "„Wehe jedem Stichler und Nörgler, der Besitz sammelt und ihn immer wieder zählt – er meint, sein Besitz mache ihn unsterblich!“ – Ibn Kathīr: Die Sure verknüpft die Verachtung der Menschen mit der Vergötzung des Geldes als EIN Krankheitsbild: Der Spott nach unten finanziert das Selbstbild, das der Besitz nach oben polstert. As-Saʿdī zu ʿaddadahu: Das Zählen ohne Geben ist die Körperhaltung des Geizes – im Gegensatz zum Zählen des Händlers, der geben will. Und zur Unsterblichkeits-Illusion: Der Besitz verlängert kein Leben um eine Stunde, aber er verkürzt vielen das Jenseits – „sein Vermögen nützt ihm nichts, wenn er stürzt“ (92:11, Lektion 9)."},
 {vers: "Verse 4–9", text: "„Keineswegs! Er wird ganz gewiss in die Zermalmende geworfen. Und was lässt dich wissen, was die Zermalmende ist? Allahs entfachtes Feuer, das über die Herzen emporsteigt. Es ist über ihnen verschlossen, in langgestreckten Säulen.“ – Al-Qurṭubī: Jedes Element antwortet auf die Tat – zermalmt, wer Ehren zermalmte; das Herz brennt, aus dem der Spott kam; eingeschlossen, wer ausgrenzte; „geworfen“ (la-yunbadhanna – wie man Wertloses wegwirft), wer Menschen wie Wertloses behandelte. Die Sunna zieht die Alltagsgrenzen: „Weißt du, was Ġība (Lästern) ist? Dass du über deinen Bruder sagst, was ihm zuwider wäre.“ – „Und wenn es stimmt?“ – „Wenn es stimmt, hast du gelästert; wenn nicht, hast du verleumdet (buhtān)“ (Sahih Muslim, Nr. 2589). Und: „Kein qattāt (Zuträger/Verhetzer) betritt das Paradies“ (Sahih al-Buchari, Nr. 6056). Der Hochmut dahinter: „Hochmut ist, die Wahrheit zurückzuweisen und die Menschen geringzuschätzen (ġamṭ an-nās)“ (Sahih Muslim, Nr. 91) – ġamṭ an-nās ist exakt das humaza-lumaza-Profil."}
],
ahadith: [
 {text: "„Weißt du, was Ġība ist? … Dass du über deinen Bruder erwähnst, was ihm zuwider ist.“ – „Und wenn an meinem Bruder ist, was ich sage?“ – „Wenn es an ihm ist, hast du Ġība begangen; wenn nicht, hast du ihn verleumdet.“", quelle: "Sahih Muslim, Nr. 2589"},
 {text: "„Es betritt kein Zuträger (qattāt / nammām – einer, der Worte weiterträgt, um zu entzweien) das Paradies.“", quelle: "Sahih al-Buchari, Nr. 6056; Sahih Muslim, Nr. 105"},
 {text: "„Der Muslim ist der, vor dessen Zunge und Hand die Muslime sicher sind.“", quelle: "Sahih al-Buchari, Nr. 10; Sahih Muslim, Nr. 40"},
 {text: "„Niemand betritt das Paradies, in dessen Herzen ein Stäubchen Hochmut ist … Hochmut ist, die Wahrheit zurückzuweisen und die Menschen geringzuschätzen.“", quelle: "Sahih Muslim, Nr. 91"}
],
hanafi: null,
umsetzung: [
 "Führe die Muslim-2589-Definition als Familienregel ein: „Würde es ihm zuwider sein?“ – dann ist es Ġība, auch wenn es stimmt. Dieser eine Satz beendet die meisten Lästerrunden.",
 "Sei der Ketten-Brecher: Wenn in deiner Gegenwart gestichelt wird, verteidige den Abwesenden oder wechsle das Thema – „Wer die Ehre seines Bruders verteidigt, dessen Gesicht hält Allah am Tag der Auferstehung vom Feuer fern“ (at-Tirmidhī, Nr. 1931; hasan).",
 "Beobachte dein ʿaddada-Ritual: Wie oft checkst du Konto/Depot/Umsätze – und wie oft dein Jenseits-Konto (Gebete, Sadaqa, Dhikr)? Stelle ein bewusstes Verhältnis her: nach jedem Finanz-Check ein Dhikr oder eine Kleinspende.",
 "Digital anwenden: Häme-Kommentare, Spott-Memes über Personen, ‚Ratio'-Kultur – alles humaza/lumaza in Reinform. Nicht liken, nicht teilen, nicht mitschreiben."
]
},

// ───────────────────────── Lektion 33: Al-Mursalāt ─────────────────────────
{
sure: 77, offb: 33, name: "Al-Mursalāt", arab: "سُورَةُ الْمُرْسَلَاتِ", de: "Die Entsandten", verse: 50, ort: "Mekka",
zeit: "Frühmekkanisch – in einer Höhle bei Minā offenbart, wie Ibn Masʿūd als Augenzeuge berichtet",
kurz: "Die Sure mit dem hämmerndsten Refrain des Korans: Zehnmal fällt der Satz „Wehe an jenem Tag den Leugnern!“ – nach jedem Beweisblock einmal, wie ein Urteil, das nach jeder Zeugenaussage erneut verlesen wird. Die Beweise: die entsandten Winde und Engel, der „Tag der Entscheidung“ (yaum al-faṣl), die vernichteten früheren Völker, deine eigene Entstehung aus „verächtlichem Wasser“, die Erde als Sammlerin der Lebenden und der Toten, die Schatten-Täuschung des Höllenrauchs und das Heil der Gottesfürchtigen. Ibn Masʿūd erzählt die Offenbarungsszene: In einer Höhle bei Minā, „während sie frisch aus seinem Mund kam“, schoss eine Schlange hervor – der Prophet ﷺ: „Sie ist vor eurem Übel bewahrt worden, wie ihr vor ihrem.“ Der Schlusssatz der Sure ist eine offene Frage an jeden Leser: „An welche Aussage nach dieser wollen sie denn (sonst) glauben?“",
schluessel: {arab: "وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ", ueb: "Wehe an jenem Tag den Leugnern!", ref: "77:15 (u. a. – zehnmal in der Sure)"},
kontext: ["Ibn Masʿūd berichtet: „Während wir mit dem Propheten ﷺ in einer Höhle bei Minā waren, kam ‚Wa-l-mursalāti ʿurfā' auf ihn herab; er rezitierte sie, und ich nahm sie frisch aus seinem Munde auf – da sprang eine Schlange auf uns zu. Der Prophet ﷺ sagte: Tötet sie! Wir eilten, doch sie entkam. Da sagte er: Sie ist vor eurem Übel bewahrt worden, wie ihr vor ihrem“ (Sahih al-Buchari, Nr. 1830 u. 4930; Sahih Muslim, Nr. 2234). Die Szene zeigt nebenbei, wie Gefährten den Koran lernten: direkt, sofort, „frisch aus seinem Mund“.",
"Die Sure gehört zur Gruppe der Refrain-Suren (vgl. 55 mit „Welche der Wohltaten…“ und 54 mit „Wir haben den Koran leicht gemacht…“). Der zehnfache Weheruf strukturiert zehn Abschnitte: Jeder bringt einen neuen Beweis oder eine neue Szene – und endet mit demselben Urteil. Rhetorisch ist das ein Gerichtsprotokoll: Beweisaufnahme, Urteil; Beweisaufnahme, Urteil.",
"Umm al-Faḍl (die Frau des ʿAbbās) hörte ihren Sohn diese Sure rezitieren und weinte: „Mein Söhnchen, du hast mich mit dieser Sure erinnert – sie ist das Letzte, was ich den Gesandten Allahs ﷺ im Maghrib-Gebet rezitieren hörte“ (Sahih al-Buchari, Nr. 763; Sahih Muslim, Nr. 462). Die Sure begleitete den Propheten ﷺ also bis in seine letzten Tage."],
asbab: [
 {text: "Ibn Masʿūd: Offenbarung in der Höhle bei Minā, die Szene mit der Schlange – „ich nahm sie frisch aus seinem Munde auf“.", quelle: "Sahih al-Buchari, Nr. 1830, 4930; Sahih Muslim, Nr. 2234"}
],
begriffe: [
 {arab: "الْمُرْسَلَات عُرْفًا", tr: "al-mursalāt ʿurfan", wurzel: "r-s-l / ʿ-r-f", erkl: "„Die in Folge Entsandten“ – nach den Mufassirūn die Winde (die aufeinanderfolgen wie Mähnenhaar, ʿurf) und/oder die Engel mit ihren Aufträgen. Die ersten fünf Schwüre beschreiben Entsandte, Stürmende, Ausbreitende, Trennende, Erinnerung-Überbringende – Allahs unsichtbare Logistik zwischen Himmel und Erde."},
 {arab: "يَوْم الْفَصْل", tr: "yaum al-faṣl", wurzel: "f-ṣ-l", erkl: "„Der Tag der Entscheidung/Trennung“ – dreimal in der Sure: der Tag, der Wahrheit von Lüge, Gerechte von Ungerechten endgültig trennt (faṣala = trennen, entscheiden). Name des Gerichts als Sortierung – nichts bleibt vermischt."},
 {arab: "كِفَاتًا", tr: "kifātan", wurzel: "k-f-t", erkl: "77:25–26: „Haben Wir nicht die Erde zu einer kifāt gemacht – für Lebende und Tote?“ Kafata: an sich ziehen, bergen. Die Erde als Sammlerin: Sie trägt dich oben und birgt dich unten. Ein einziges Wort als Memento mori – du läufst auf deinem künftigen Aufbewahrungsort."},
 {arab: "مَاء مَّهِين", tr: "māʾ mahīn", wurzel: "m-h-n", erkl: "„Verächtliches (unscheinbares) Wasser“ (77:20) – deine Rohmasse. Das Argument (wie 75:37, Lektion 31): Wer dich aus einem Tropfen in „festem Behältnis“ bis zum bestimmten Maß formte, dem ist die Wiederholung leicht. „Wir haben bemessen (qaddarnā) – wie trefflich bemessen Wir!“"},
 {arab: "ظِلّ ذِي ثَلَاثِ شُعَب", tr: "ẓill dhī thalāthi schuʿab", wurzel: "ẓ-l-l / sch-ʿ-b", erkl: "„Ein Schatten mit drei Verzweigungen“ (77:30) – der Höllenrauch, der sich wie ‚Schatten' anbietet, „der nicht schattet und nicht vor der Flamme nützt“: die große Täuschung – was Schutz verspricht und keiner ist. Gegenbild: „Die Gottesfürchtigen sind in (wirklichen) Schatten und an Quellen“ (77:41)."},
 {arab: "اركَعُوا", tr: "irkaʿū", wurzel: "r-k-ʿ", erkl: "77:48: „Und wenn zu ihnen gesagt wird: Verbeugt euch!, verbeugen sie sich nicht.“ – Die einzige konkrete Tat, an der die Sure die Leugner misst, ist das Gebet: Rukūʿ als Testfall der Unterwerfung. Wer sich hier nicht beugt – „an welche Aussage danach wollen sie glauben?“"}
],
tafsir: [
 {vers: "Verse 1–15", text: "Fünf Schwüre bei den Entsandten, dann die Zusage: „Was euch versprochen wird, wird gewiss eintreffen“ – und die Kulisse des Tages: ausgelöschte Sterne, gespaltener Himmel, zerstäubte Berge, und die Gesandten, die zu ihrem „Termin“ (uqqitat) als Zeugen gegen ihre Völker geladen werden. „Für welchen Tag ist (das alles) aufgeschoben? Für den Tag der Entscheidung!“ – dann zum ersten Mal der Refrain. As-Saʿdī: Der Weheruf gilt den mukadhdhibīn – nicht den Zweiflern, die suchen, sondern den Leugnern, die abtun; das Wort trägt Aktivität: für Lüge ERKLÄREN, trotz Beweis."},
 {vers: "Verse 16–28", text: "Drei Beweisblöcke, je mit Urteil: (1) Geschichte – „Haben Wir nicht die Früheren vernichtet und lassen die Späteren ihnen folgen? So verfahren Wir mit den Übeltätern.“ (2) Embryologie – das verächtliche Wasser, das feste Behältnis, das bestimmte Maß. (3) Geografie – die Erde als kifāt für Lebende und Tote, mit festgegründeten Bergen und süßem Wasser. Ibn Kathīr: Die Beweise wandern von außen (Geschichte) über innen (deine Entstehung) zum Boden unter den Füßen – der Leugner wird eingekreist von Zeugnissen, auf denen er steht, aus denen er besteht und über die er läuft."},
 {vers: "Verse 29–40", text: "Die bittere Einladung: „Zieht los zu dem, was ihr für Lüge erklärt habt! Zieht los zu einem Schatten mit drei Verzweigungen, der nicht schattet …“ – das Feuer sprüht Funken „wie Burgen, als wären sie gelbe Kamelhengste“ (die Araber kannten nichts Größeres als Festungen, nichts Prächtigeres als gelbbraune Kamelherden – beide Bilder vereint im Funkenflug). „Dies ist der Tag, an dem sie nicht reden und ihnen nicht erlaubt wird, sich zu entschuldigen.“ Al-Qurṭubī: Das Verstummen der Wortgewaltigen – die in der Dunya jede Wahrheit zerredeten, verlieren als Erstes das Wort."},
 {vers: "Verse 41–50", text: "Der Gegenschnitt: „Die Gottesfürchtigen sind in Schatten und an Quellen und (haben) Früchte, was sie begehren. Esst und trinkt als wohlbekömmlich für das, was ihr zu tun pflegtet – so vergelten Wir den Gutes-Tuenden (muḥsinīn).“ Dann die letzte Warnung an die Leugner: „Esst und genießt ein wenig – ihr seid Übeltäter“ (das Diesseits als kurze Gnadenfrist), der Rukūʿ-Test (V. 48) und die Schlussfrage: „An welche Aussage nach dieser (fa-bi-ayyi ḥadīthin baʿdahū) wollen sie glauben?“ – Ibn Kathīr: Wenn dieser Koran – mit seiner Sprache, seinen Beweisen, seiner Bewahrung – nicht überzeugt, welcher Text soll es dann? Die Frage steht am Ende wie ein offenes Tor: Sie zwingt nicht, sie stellt."}
],
ahadith: [
 {text: "Ibn Masʿūd: die Offenbarungsszene in der Höhle von Minā mit der Schlange – „sie ist vor eurem Übel bewahrt worden, wie ihr vor ihrem“.", quelle: "Sahih al-Buchari, Nr. 1830; Sahih Muslim, Nr. 2234"},
 {text: "Umm al-Faḍl: „… sie ist das Letzte, was ich den Gesandten Allahs ﷺ im Maghrib rezitieren hörte.“", quelle: "Sahih al-Buchari, Nr. 763; Sahih Muslim, Nr. 462"},
 {text: "„Zwischen dem Mann und dem Schirk/Unglauben steht das Unterlassen des Gebets.“ – zum Rukūʿ-Test von 77:48.", quelle: "Sahih Muslim, Nr. 82"}
],
hanafi: null,
umsetzung: [
 "Lies die Sure einmal mit Refrain-Bewusstsein: Markiere die zehn Weherufe und benenne für jeden Block den Beweis davor – so lernst du die koranische Argumentationskunst kennen (und kannst sie weitergeben).",
 "Nimm den kifāt-Spaziergang: Geh bewusst über die Erde mit dem Gedanken „Sammlerin der Lebenden und der Toten – auch meine“. Das ist Dhikr al-maut ohne ein einziges düsteres Buch.",
 "Prüfe deine ‚Drei-Zweige-Schatten': Welche Scheinschutz-Strategien nutzt du gegen die Wahrheit (Ablenkung, Zynismus, ‚später')? Sie schatten nicht. Echter Schatten steht bei den Muttaqīn – Gebet, Koran, gute Gesellschaft.",
 "Der Rukūʿ-Test ist dein Frühwarnsystem: Wenn das Gebet schwer wird, behandle es als Alarmstufe eins (vgl. Muslim 82) – nicht als Phase. Sofort gegensteuern: Gemeinschaftsgebet, kürzere aber pünktliche Gebete, Duʿā um Festigung."
]
},

// ───────────────────────── Lektion 34: Qāf ─────────────────────────
{
sure: 50, offb: 34, name: "Qāf", arab: "سُورَةُ قٓ", de: "Qāf", verse: 45, ort: "Mekka",
zeit: "Mittelmekkanisch – die Sure, die der Prophet ﷺ in Freitags- und Festpredigten immer wieder öffentlich rezitierte",
kurz: "Wenn du wissen willst, was der Prophet ﷺ den Massen predigte, lies Qāf: Umm Hischām bint Ḥāritha sagte, sie habe die Sure „direkt aus dem Mund des Gesandten Allahs“ gelernt – von seinen Freitagspredigten, in denen er sie immer wieder rezitierte. Ihr Inhalt ist das Kerncurriculum: Die Verwunderung der Leugner über Auferstehung („eine weit entfernte Rückkehr!“) – und die Antwort: „Wir wissen, was die Erde von ihnen verringert; bei Uns ist ein bewahrendes Buch.“ Dann die zwei berühmtesten Nähe-Verse des Korans: „Wir sind ihm näher als seine Halsschlagader“ und die zwei Schreiber-Engel: „Kein Wort äußert er, ohne dass bei ihm ein Beobachter bereit wäre.“ Es folgen Sterbestunde („Der Todeskampf kommt mit der Wahrheit – das ist es, wovor du auszuweichen pflegtest“), Gericht, das unersättliche Feuer („Gibt es noch mehr?“) und das Paradies für „jeden Reumütigen, (Allahs) Achtsamen … der mit einem einsichtigen Herzen (qalb munīb) kommt“. Schluss: „Ermahne mit dem Koran, wer Meine Drohung fürchtet“ – Daʿwa ohne Zwang: „Du bist kein Zwingherr über sie.“",
schluessel: {arab: "وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ", ueb: "Und Wir sind ihm näher als seine Halsschlagader.", ref: "50:16"},
kontext: ["Diese Sure war öffentliches Dauerprogramm des Propheten ﷺ: Umm Hischām lernte sie komplett von seinen Minbar-Rezitationen am Freitag (Sahih Muslim, Nr. 872–873); an den beiden Festen rezitierte er im Gebet „Qāf“ und „Iqtarabat“ (Sure 54) (Sahih Muslim, Nr. 891). Die Gelehrten folgern: Qāf enthält, was JEDER Muslim regelmäßig hören soll – das Curriculum der Erinnerung: Schöpfung, Tod, Auferstehung, Aufzeichnung, Gericht, Paradies und Hölle.",
"Der rote Faden ist die Antwort auf EINEN Einwand (50:3): „Wenn wir gestorben und zu Erde geworden sind…? Das ist eine weit entfernte Rückkehr!“ Die Sure antwortet dreigleisig: (1) Wissen – Allah weiß, „was die Erde von ihnen verringert“; kein Atom des Körpers geht Ihm verloren, alles steht im „bewahrenden Buch“. (2) Schöpfungsbeweis – schaut auf den Himmel „ohne Risse“, die Erde, die Berge, „jede herrliche Art“; und der Regen, der totes Land belebt: „So ist das Herauskommen (al-churūdsch)“. (3) Geschichte – die Völker vor euch, die leugneten.",
"Für dein Tazkiya-Thema sind die Verse 16–18 zentral: Allahs Nähe („näher als die Halsschlagader“ – Nähe des Wissens und der Macht, so die Mufassirūn, bei Erhabenheit über der Schöpfung) plus die zwei Engel rechts und links (raqīb ʿatīd), die jedes Wort erfassen. Wer beides verinnerlicht, braucht keine Kamera-Metapher mehr: Die Aufsicht ist liebevoll, lückenlos und längst installiert."],
asbab: ["Kein spezifischer Offenbarungsanlass überliefert. Zur öffentlichen Rolle der Sure: Umm Hischām bint Ḥāritha: „Ich habe ‚Qāf wa-l-qurʾāni l-madschīd' direkt aus dem Mund des Gesandten Allahs ﷺ gelernt – er rezitierte sie jeden Freitag auf dem Minbar, wenn er zu den Leuten predigte“ (Sahih Muslim, Nr. 873)."],
begriffe: [
 {arab: "كِتَاب حَفِيظ", tr: "kitāb ḥafīẓ", wurzel: "ḥ-f-ẓ", erkl: "„Ein bewahrendes Buch“ (50:4) – die lückenlose Registratur: Was die Erde von den Körpern ‚frisst', ist bei Allah verbucht. Dieselbe Wurzel wie ḥāfiẓ (Hüter, vgl. 86:4, Lektion 36) und Koran-Ḥifẓ: Bewahrung ist ein Gottesattribut."},
 {arab: "حَبْل الْوَرِيد", tr: "ḥabl al-warīd", wurzel: "w-r-d", erkl: "Die Halsschlagader – Bild für das Innerste und Lebensnächste. „Näher als sie“ ist Allah mit Wissen, Macht und Umfassung (so aṭ-Ṭabarī; nach manchen: durch Seine Engel) – der Vers nimmt dem Menschen jede Vorstellung von Distanz, ohne Allahs Erhabenheit anzutasten."},
 {arab: "رَقِيب عَتِيد", tr: "raqīb ʿatīd", wurzel: "r-q-b / ʿ-t-d", erkl: "„Beobachter, bereit“ (50:18) – die beiden Schreiber-Engel (rechts: die guten Taten, links: die schlechten; vgl. 82:10–12). Kein Wort fällt unprotokolliert – deshalb zählten die Frühgelehrten das Schweigen zur ʿIbāda."},
 {arab: "سَكْرَة الْمَوْت", tr: "sakrat al-maut", wurzel: "s-k-r", erkl: "„Der Rausch/Taumel des Todes“ (50:19) – die Agonie, „mit der Wahrheit“ kommend: Sie beendet jede Illusion. Der Prophet ﷺ sprach in seinem Sterben: „Lā ilāha illa llāh – der Tod hat wahrlich Räusche“ (Sahih al-Buchari, Nr. 6510)."},
 {arab: "هَلْ مِن مَّزِيد", tr: "hal min mazīd", wurzel: "z-y-d", erkl: "„Gibt es noch mehr?“ (50:30) – die Antwort der Hölle auf die Frage „Bist du voll?“. Der Hadith erklärt: Sie wird erst gestillt, wenn der Herr der Ehre Seinen Fuß auf sie setzt und sie sagt: „Genug, genug!“ (Sahih al-Buchari, Nr. 4848–4849; Eigenschaftstexte werden bestätigt, ohne das ‚Wie' zu deuten)."},
 {arab: "قَلْب مُنِيب", tr: "qalb munīb", wurzel: "n-w-b", erkl: "„Ein (reuig) zugewandtes Herz“ (50:33) – von anāba: immer wieder zurückkehren. Das Paradies-Profil der Sure: awwāb (oft Umkehrender), ḥafīẓ (Bewahrer des Bundes), Allah im Verborgenen fürchtend, mit munīb-Herz kommend. Vier Eigenschaften – alle Herzensarbeit."},
 {arab: "ذِكْرَىٰ لِمَن كَانَ لَهُۥ قَلْب", tr: "dhikrā li-man kāna lahū qalb", wurzel: "q-l-b", erkl: "50:37: „Darin ist Erinnerung für den, der ein Herz hat oder hinhört, während er Zeuge ist (schahīd – innerlich anwesend).“ – Die Hör-Bedingungen des Korans: ein lebendiges Herz ODER volle Präsenz. Zerstreutes Hören erreicht nichts; die Sure nennt ihre eigene Gebrauchsanweisung."}
],
tafsir: [
 {vers: "Verse 1–15", text: "Nach Schwur („Qāf. Beim ruhmvollen Koran!“) und Einwand der Leugner die dreifache Antwort. Zum Schöpfungsteil: „Schauen sie nicht zum Himmel über ihnen, wie Wir ihn aufgebaut und geschmückt haben – er hat keine Risse (furūdsch)?“ – dazu Erde, Berge, „jedes herrliche Paar“ – als „tabṣira wa-dhikrā (Einsicht und Erinnerung) für jeden reuig zugewandten Diener“. Dann der Regen-Beweis: Gärten, Korn, hochragende Palmen „als Versorgung für die Diener; und Wir machen damit totes Land lebendig – so ist das Herauskommen (aus den Gräbern).“ Ibn Kathīr: Der Frühling ist die jährliche Generalprobe der Auferstehung vor aller Augen. Abschluss: sieben frühere Völker, die leugneten – „ist Uns denn die erste Schöpfung schwergefallen? Nein, sie sind im Zweifel über eine neue Schöpfung“ (V. 15)."},
 {vers: "Verse 16–29", text: "„Wir haben den Menschen erschaffen und wissen, was seine Seele ihm einflüstert (tuwaswisu – vgl. Lektion 21!), und Wir sind ihm näher als seine Halsschlagader.“ Dazu die Protokollanten (raqīb ʿatīd), der Todestaumel „mit der Wahrheit“, der Posaunenstoß – und die Ankunft: „Jede Seele kommt, mit ihr ein Treiber und ein Zeuge. Du warst dessen unachtsam (fī ġafla) – nun haben Wir deine Decke von dir genommen, und scharf ist heute dein Blick.“ As-Saʿdī: Ġafla (Achtlosigkeit) ist die ‚Decke' des Diesseits; der Tod zieht sie weg – Tazkiya ist der Versuch, sie schon vorher zu lüften. Es folgt der Streit des Menschen mit seinem Dämonen-Gefährten (qarīn) – „Unser Herr, ICH habe ihn nicht auflehnen lassen, er selbst war im tiefen Irrtum“ – und Allahs Schlusswort: „Streitet nicht vor Mir … Das Wort wird bei Mir nicht abgeändert, und Ich bin keiner, der den Dienern Unrecht tut (ẓallāmin li-l-ʿabīd).“"},
 {vers: "Verse 30–35", text: "Hölle: „Bist du voll?“ – „Gibt es noch mehr?“ (mit dem Buchari-Hadith verstanden). Paradies: „nahe herangebracht den Gottesfürchtigen – nicht fern: Das ist, was jedem versprochen ist, der awwāb und ḥafīẓ ist, der den Allerbarmer im Verborgenen fürchtet und mit einem zugewandten Herzen kommt. Betretet es in Frieden – das ist der Tag der Ewigkeit. Darin haben sie, was sie wollen – und bei Uns ist noch mehr (wa-ladainā mazīd).“ – Al-Qurṭubī: wa-ladainā mazīd deuteten die Gefährten auf das Schauen zu Allah (vgl. 75:23, Lektion 31; und 10:26 „al-ḥusnā wa-ziyāda“, durch Sahih Muslim, Nr. 181 als das Schauen erklärt): Das ‚Mehr' über alle Wünsche hinaus ist Er selbst."},
 {vers: "Verse 36–45", text: "Die Schluss-Anweisungen an den Propheten ﷺ – und an jeden Lehrer: Geduld mit dem Gerede, Tasbīḥ „vor Sonnenaufgang und vor Sonnenuntergang“ (Fadschr und ʿAṣr – vgl. Buchari 554 in Lektion 31!) und in der Nacht, Erinnerung an den Tag des Rufes. Und das Daʿwa-Prinzip als Schlussvers: „Wir wissen am besten, was sie sagen, und du bist kein Zwingherr (dschabbār) über sie. So ermahne mit dem Koran, wer Meine Drohung fürchtet (fa-dhakkir bi-l-qurʾāni man yachāfu waʿīd).“ – Ibn Kathīr: Das Werkzeug der Ermahnung ist der Koran selbst – nicht Druck, nicht Tricks; und die Zielgruppe sind die erreichbaren Herzen. Der Prophet ﷺ hat das wörtlich gelebt: Er ermahnte die Massen Freitag für Freitag – mit genau dieser Sure."}
],
ahadith: [
 {text: "Umm Hischām: „Ich lernte ‚Qāf wa-l-qurʾāni l-madschīd' aus dem Mund des Gesandten Allahs ﷺ – er rezitierte sie jeden Freitag auf dem Minbar.“ / An den Festen rezitierte er Qāf und Iqtarabat.", quelle: "Sahih Muslim, Nr. 872–873 und 891"},
 {text: "Der Hölle-Dialog zu 50:30: „Die Hölle hört nicht auf zu sagen: Gibt es noch mehr? – bis der Herr der Ehre Seinen Fuß auf sie setzt; da sagt sie: Genug, genug, bei Deiner Ehre! – und sie zieht sich zusammen.“", quelle: "Sahih al-Buchari, Nr. 4848; Sahih Muslim, Nr. 2848"},
 {text: "Zu „bei Uns ist noch mehr“: „Wenn die Bewohner des Paradieses das Paradies betreten haben, ruft ein Rufer: Ihr habt bei Allah noch ein Versprechen … Da wird der Schleier gelüftet, und ihnen wird nichts Lieberes gegeben worden sein als der Blick auf ihren Herrn.“", quelle: "Sahih Muslim, Nr. 181 (zu 10:26, von den Gelehrten mit 50:35 verbunden)"}
],
hanafi: "Aus der Minbar-Praxis des Propheten ﷺ mit dieser Sure leiten die Fuqahāʾ die Sunna ab, in der Freitagspredigt Koran zu rezitieren – hanafitisch gehört zur gültigen Chuṭba mindestens Dhikr Allahs, und die Rezitation wenigstens eines Verses in der Predigt ist Sunna. Für die Zuhörer gilt hanafitisch: Während der Chuṭba ist Schweigen und Zuhören wādschib – selbst das ‚Gutes gebieten' unterbleibt in dieser Zeit („Wenn du zu deinem Gefährten am Freitag, während der Imam predigt, sagst: ‚Schweig!', hast du schon Unfug geredet“ – Sahih al-Buchari, Nr. 934; Sahih Muslim, Nr. 851). Praktisch: Freitags früh kommen, nichts reden, hinhören – die Sure selbst nennt die Bedingung: „für den, der ein Herz hat oder hinhört, während er innerlich anwesend ist“ (50:37).",
umsetzung: [
 "Verinnerliche 50:16+18 als Doppel-Bewusstsein für eine Woche: Näher als die Halsschlagader + kein Wort unprotokolliert. Sprich-Test vor jedem Satz über Abwesende: „raqīb ʿatīd hört mit.“",
 "Behandle den Freitag als deine Qāf-Stunde: früh da sein, Chuṭba mit voller Präsenz (50:37), danach einen Gedanken der Predigt notieren und einem Familienmitglied weitergeben.",
 "Bete bewusst um das qalb munīb: Nimm die vier Paradies-Eigenschaften aus 50:32–33 (awwāb, ḥafīẓ, Furcht im Verborgenen, zugewandtes Herz) als Monats-Checkliste deiner Tazkiya.",
 "Lerne die Frühlings-Lektion (50:9–11): Jedes Mal, wenn du totes Land grün werden siehst, sprich innerlich „kadhālika l-churūdsch – so ist das Herauskommen“. Der Koran will, dass die Natur dich an die Auferstehung erinnert."
]
},

// ───────────────────────── Lektion 35: Al-Balad ─────────────────────────
{
sure: 90, offb: 35, name: "Al-Balad", arab: "سُورَةُ الْبَلَدِ", de: "Die Ortschaft", verse: 20, ort: "Mekka",
zeit: "Frühmekkanisch – Schwur bei Mekka, gerichtet an eine Elite, die Religion ohne Kosten wollte",
kurz: "Allah schwört bei Mekka – „und du (Prophet) bist Bewohner dieser Ortschaft“ – auf einen Satz, der alle Wohlfühl-Illusionen beendet: „Wir haben den Menschen wahrlich in Mühsal (kabad) erschaffen.“ Das Leben IST anstrengend – die Frage ist nur, wofür du dich abmühst. Der Prahler sagt: „Ich habe haufenweise Vermögen vernichtet“ (verprasst für Prestige). Der Koran antwortet mit der Alternative: al-ʿAqaba, der steile Pass – „Und was lässt dich wissen, was der steile Pass ist? Einen Nacken befreien (einen Sklaven freikaufen) oder Speisung an einem Tag der Hungersnot: eine verwandte Waise oder einen Armen, der am Boden liegt.“ Und dann – weil Taten allein nicht tragen – „hierauf gehört er zu denen, die glauben und einander die Geduld und die Barmherzigkeit ans Herz legen.“ Bergauf-Ausgeben für Menschen plus Īmān plus Gemeinschaft: Das ist der Weg zur rechten Seite (aṣḥāb al-maimana).",
schluessel: {arab: "فَلَا اقْتَحَمَ الْعَقَبَةَ ۝ وَمَا أَدْرَاكَ مَا الْعَقَبَةُ ۝ فَكُّ رَقَبَةٍ", ueb: "Aber er hat den steilen Pass nicht erklommen. Und was lässt dich wissen, was der steile Pass ist? Einen Nacken (vom Joch) zu befreien …", ref: "90:11–13"},
kontext: ["Der Schwur bei Mekka trägt eine doppelte Spitze: „wa-anta ḥillun bi-hādhā l-balad“ – gedeutet als „während du in dieser Stadt wohnst“ (die Stadt wird durch dich noch ehrwürdiger) UND als Prophezeiung: „während dir diese Stadt (einst) freigegeben sein wird“ – erfüllt am Tag der Eroberung, als Mekka dem Propheten ﷺ „eine Stunde eines Tages“ freigegeben wurde (Sahih al-Buchari, Nr. 104 – vgl. Lektion 19!). Dieselben Mekkaner, die das Heiligtum für sich beanspruchten, verletzten die Heiligkeit des Besten ihrer Bewohner.",
"Zielscheibe der Sure ist der Typ des Status-Verschwenders: „Meint er, dass niemand Macht über ihn hat? Er sagt: Ich habe haufenweise (lubadā) Vermögen vernichtet.“ – Die Araber rühmten sich öffentlicher Verschwendung (Festessen, Kamelschlachten, Fehden-Finanzierung) als Ehre. Der Koran fragt: „Meint er, dass niemand ihn gesehen hat?“ – und stellt der Prestige-Verschwendung die ʿAqaba-Ausgaben gegenüber: Sklaven freikaufen, Hungrige speisen. Beides kostet – aber eines kauft Ruhm bei Menschen, das andere den Aufstieg bei Allah.",
"Die Gaben-Trias der Verse 8–10 begründet die Verantwortung: „Haben Wir ihm nicht zwei Augen gemacht, eine Zunge und zwei Lippen – und ihm die beiden Anhöhen (an-nadschdain: die zwei Wege) gezeigt?“ Ausstattung plus Wegweisung = Rechenschaft. Niemand kann sagen, er habe die Abzweigung nicht gesehen."],
asbab: ["Kein sahih gesicherter Einzelanlass; die Tafsir-Werke nennen für den Prahler der Verse 5–7 Kandidaten der mekkanischen Elite (u. a. al-Walīd, Abū l-Aschadd – ein für seine Körperkraft berühmter Mann, der sich unbesiegbar wähnte). Der Wortlaut bleibt allgemein: jeder Kraft- und Geldprotz ist gemeint."],
begriffe: [
 {arab: "كَبَد", tr: "kabad", wurzel: "k-b-d", erkl: "Mühsal, Plage, Anstrengung – verwandt mit kabid (Leber: Sitz der Mühe im arabischen Körperbild). 90:4: Der Mensch ist IN Mühsal erschaffen – von Geburt bis Grab. Der Koran verspricht kein müheloses Leben, sondern sinnvolle Mühe; wer Mühelosigkeit erwartet, zerbricht an der Normalität."},
 {arab: "لُبَدًا", tr: "lubadan", wurzel: "l-b-d", erkl: "„Haufenweise, aufgeschichtet“ (90:6) – Vermögen „vernichtet“ (ahlaktu) für Show: Der Prahler nennt sein Verprassen selbst Vernichtung. Präziser kann Selbstentlarvung nicht sein – Status-Konsum IST Vermögensvernichtung."},
 {arab: "النَّجْدَيْن", tr: "an-nadschdain", wurzel: "n-dsch-d", erkl: "„Die beiden Anhöhen“ (90:10) – die zwei erkennbaren Wege: gut und böse (vgl. 76:3; 91:8, Lektion 26). Nadschd ist das sichtbar erhöhte Gelände: Beide Wege liegen offen da – keiner läuft versehentlich falsch."},
 {arab: "الْعَقَبَة", tr: "al-ʿaqaba", wurzel: "ʿ-q-b", erkl: "Der steile (Berg-)Pass – das Nadelöhr des Weges. Iqtaḥama: sich hineinstürzen, bezwingen. Das Paradies liegt bergauf; die Sure nennt die Serpentinen beim Namen: Freikauf, Speisung, Īmān, gegenseitige Stärkung. Bergab geht es von allein."},
 {arab: "فَكّ رَقَبَة", tr: "fakk raqaba", wurzel: "f-k-k / r-q-b", erkl: "„Einen Nacken lösen“ – einen Sklaven freikaufen: die vom Koran an erster Stelle genannte ʿAqaba-Tat (vgl. die Freikäufe Abū Bakrs, Lektion 9!). Heute analog: Menschen aus Schuldknechtschaft, Gefangenschaft, Zwangslagen lösen."},
 {arab: "مَسْغَبَة / مَتْرَبَة", tr: "masġaba / matraba", wurzel: "s-ġ-b / t-r-b", erkl: "„Tag des Hungers“ und „im Staub liegend“ – Speisung dann, wenn sie wehtut (Knappheit), für den, der ganz unten liegt (matraba: am Staub klebend). Der Koran bemisst Taten nach Bedarf und Zeitpunkt, nicht nach Bequemlichkeit."},
 {arab: "الْمَرْحَمَة", tr: "al-marḥama", wurzel: "r-ḥ-m", erkl: "90:17: „… und einander die Barmherzigkeit ans Herz legen (tawāṣau bi-l-marḥama)“ – das Schwester-Wort zu tawāṣau bi-ṣ-ṣabr (vgl. Al-ʿAṣr, Lektion 13!): Eine Gemeinschaft, die sich gegenseitig zu Geduld UND Erbarmen verpflichtet. Marḥama als Gemeinschaftskultur, nicht nur Privatgefühl."}
],
tafsir: [
 {vers: "Verse 1–7", text: "Schwur bei der Stadt, ihrem Bewohner ﷺ und „dem Zeugenden und dem, was er gezeugt hat“ (Ādam und seine Nachkommen, nach anderen allgemein Eltern und Kinder – die Kette der Mühsal von Generation zu Generation): „Wir haben den Menschen wahrlich in kabad erschaffen.“ Ibn Kathīr: Die Mühsal ist Schöpfungsmerkmal, nicht Betriebsunfall – vom Durchschneiden der Nabelschnur bis zum letzten Atemzug; entscheidend ist, in wessen Dienst sie steht. Dann der Kraft- und Geldprotz: „Meint er, dass niemand über ihn Macht hat? … Meint er, dass ihn niemand gesehen hat?“ – die doppelte Illusion der Stärke: unantastbar und unbeobachtet. Beide Fragen sind rhetorische Abrissbirnen."},
 {vers: "Verse 8–16", text: "Die Gaben-Trias (Augen, Zunge, Lippen) und die gezeigten zwei Anhöhen – dann der Vorwurf: „Aber er hat den steilen Pass nicht bezwungen (fa-lā qtaḥama l-ʿaqaba).“ Die Auflösung in Koran-eigener Frageform: „Einen Nacken befreien oder Speisung an einem Tag der Hungersnot: eine Waise aus der Verwandtschaft oder einen Armen im Staub.“ As-Saʿdī: Beachte die Präzisierung ‚Waise AUS DER VERWANDTSCHAFT' – Blutsnähe verdoppelt das Recht (Sadaqa + Ṣilat ar-raḥim); und ‚Tag des Hungers' – die Tat zur Unzeit des Gebens ist die schwerste und schwerste-wiegende. Die Sunna setzt die Preise: „Wer einen gläubigen Sklaven befreit, für den befreit Allah mit jedem Glied (des Sklaven) ein Glied von ihm aus dem Feuer“ (Sahih al-Buchari, Nr. 2517; Sahih Muslim, Nr. 1509)."},
 {vers: "Verse 17–20", text: "„Hierauf (thumma) gehört er zu denjenigen, die glauben und einander die Geduld ans Herz legen und einander die Barmherzigkeit ans Herz legen: Das sind die Gefährten der rechten Seite.“ – Al-Qurṭubī zum thumma: kein Zeit-, sondern ein Rang-Danach – die Taten der Verse 13–16 erhalten ihren Jenseitswert erst im Rahmen des Īmān; zugleich zeigt die Reihung, dass gelebte Barmherzigkeit und Glaube zusammengehören wie in Al-ʿAṣr Wahrheit und Geduld. Gegenbild: „Diejenigen aber, die Unsere Zeichen verleugnen, sind die Gefährten der linken Seite (al-maschʾama) – über ihnen ist ein verschlossenes Feuer (nār muʾṣada)“ – dasselbe Wort wie am Ende von Al-Humaza (Lektion 32): Der Kreis der Woche schließt sich."}
],
ahadith: [
 {text: "„Wer einen gläubigen Sklaven befreit, für den befreit Allah mit jedem Glied ein Glied von ihm aus dem Feuer – sogar sein Geschlechtsteil für dessen Geschlechtsteil.“", quelle: "Sahih al-Buchari, Nr. 2517; Sahih Muslim, Nr. 1509"},
 {text: "Ein Beduine fragte nach einer Tat, die ins Paradies führt. Der Prophet ﷺ: „… Befreie die Seele (den Sklaven) und löse den Nacken.“ – „Sind das nicht dasselbe?“ – „Nein: Die Seele befreien heißt, allein freizukaufen; den Nacken lösen heißt, beim Preis zu helfen“ – auch Teil-Hilfe zählt als ʿAqaba-Tat.", quelle: "Musnad Aḥmad, Nr. 18647; von den Hadith-Gelehrten als verlässlich eingestuft (al-Albānī: sahih)"},
 {text: "„Den Barmherzigen erbarmt sich der Allerbarmer – erbarmt euch derer auf der Erde, dann erbarmt sich euer, Der im Himmel ist.“ – zu tawāṣau bi-l-marḥama.", quelle: "Sunan Abū Dāwūd, Nr. 4941; at-Tirmidhī, Nr. 1924; sahih"}
],
hanafi: null,
umsetzung: [
 "Kalibriere deine Erwartung mit 90:4: Das Leben ist kabad – plane Mühe ein, statt dich von ihr überraschen zu lassen. Frage nicht „warum ist es schwer?“, sondern „für wen trage ich es?“.",
 "Such dir deine fakk-raqaba-Entsprechung: Schuldenbefreiung für eine bedrängte Familie, Auslösen von Gefangenen über seriöse Organisationen, Bürgschaft/Starthilfe – und wenn allein zu groß: anteilig (der Aḥmad-Hadith adelt ausdrücklich die Teil-Hilfe).",
 "Übe das Geben zur Unzeit (masġaba-Prinzip): Spende gerade dann, wenn es bei dir knapp ist oder die Not am größten (Krisen, Winter, Ramadan-Ende) – diese Gaben wiegen nach dieser Sure am schwersten.",
 "Baue die marḥama-Kultur im Kleinen: In Familie/Unterricht einander ausdrücklich zu Barmherzigkeit ermahnen – z. B. die Wochenfrage: „Wem waren wir diese Woche barmherzig?“ neben der Geduldsfrage aus Lektion 13."
]
},

// ───────────────────────── Lektion 36: Aṭ-Ṭāriq ─────────────────────────
{
sure: 86, offb: 36, name: "Aṭ-Ṭāriq", arab: "سُورَةُ الطَّارِقِ", de: "Der Nachtstern", verse: 17, ort: "Mekka",
zeit: "Frühmekkanisch – Schwur beim nächtlichen Stern über Bewahrung, Herkunft und Rückkehr des Menschen",
kurz: "„Beim Himmel und dem Pochenden (aṭ-ṭāriq) … dem durchbohrend hellen Stern!“ – ṭāriq ist der, der nachts anklopft: der Stern, der die Dunkelheit durchschlägt. Beschworen wird ein Satz von sieben Wörtern, der die ganze Sure trägt: „Es gibt keine Seele, über der nicht ein Hüter wäre (in kullu nafsin lammā ʿalaihā ḥāfiẓ).“ Dann der Herkunfts-Beweis: Der Mensch, erschaffen aus „sich ergießendem Wasser“, das zwischen Lenden und Brustbein hervorkommt – „gewiss hat Er die Macht, ihn zurückzubringen, am Tag, da die Geheimnisse geprüft werden (yauma tublā s-sarāʾir)“: Dann steht der Mensch ohne Kraft und ohne Helfer. Es folgt der Doppelschwur bei Himmel und Erde: Dieser Koran ist „ein entscheidendes Wort und kein Scherz (qaulun faṣl, wa-mā huwa bi-l-hazl)“. Und das Finale ist Allahs souveräne Antwort auf alle Verschwörungen: „Sie schmieden eine List, und Ich schmiede eine List. So lass den Ungläubigen Zeit – lass ihnen ein wenig Zeit (amhilhum ruwaidā).“",
schluessel: {arab: "إِن كُلُّ نَفْسٍ لَّمَّا عَلَيْهَا حَافِظٌ", ueb: "Es gibt keine Seele, über der nicht ein Hüter wäre.", ref: "86:4"},
kontext: ["Die Sure arbeitet mit dem Nacht-Setting Mekkas: Der einsame Stern, der die Finsternis durchbohrt (an-nadschm ath-thāqib), als Schwurzeuge dafür, dass KEINE Seele unbeobachtet durch die Nacht geht – weder die des Verfolgten (Trost: dein Hüter wacht) noch die des Verschwörers (Warnung: dein Protokollant schreibt). Ḥāfiẓ umfasst nach den Mufassirūn beides: die bewahrenden Engel, die den Menschen „von vorn und hinten“ behüten (13:11), und die schreibenden (vgl. raqīb ʿatīd, Lektion 34; 82:10–12: „über euch sind Hüter, edle Schreibende“).",
"Der Mittelteil beantwortet den Dauereinwand Mekkas (Auferstehung) mit dem intimsten aller Beweise – der eigenen Zeugung: „So schaue der Mensch, woraus er erschaffen wurde: aus sich ergießendem Wasser, das zwischen ṣulb (Lende/Rückgrat) und tarāʾib (Brustbein) hervorkommt.“ Wer aus einem Tropfen einen Menschen mit Hüter-Engeln macht, „hat gewiss die Macht, ihn zurückzubringen“ – dieselbe Beweisfigur wie 75:37 (Lektion 31) und 77:20 (Lektion 33), hier aufs Kürzeste verdichtet.",
"Der Schluss spricht in die Verschwörungslage der Daʿwa: Die Quraisch planten gegen den Propheten ﷺ mit allen Mitteln (Spott, Boykott, später Mordpläne – vgl. 8:30: „Und als die Ungläubigen Ränke gegen dich schmiedeten …“). Die Antwort des Himmels ist von majestätischer Gelassenheit: kaid gegen kaid – aber Allahs ‚List' ist die souveräne Lenkung der Geschichte; und der Befehl an den Verfolgten lautet nicht „schlag zurück“, sondern „gib ihnen ein wenig Zeit“ – ruwaidā, ein Wort wie ein Lächeln über die Kurzatmigkeit aller Verschwörungen."],
asbab: ["Kein sahih überlieferter Einzelanlass. Die Sure spricht in die allgemeine mekkanische Lage: Leugnung der Auferstehung und nächtliches Ränkeschmieden der Gegner (vgl. 86:15–17)."],
begriffe: [
 {arab: "الطَّارِق", tr: "aṭ-ṭāriq", wurzel: "ṭ-r-q", erkl: "„Der nachts Kommende/Anklopfende“ – von ṭaraqa: nachts anklopfen (daher ṭarīq, der Weg, den man ‚beklopft'). Hier: der Nachtstern. Der Koran fragt selbst nach („Und was lässt dich wissen, was aṭ-ṭāriq ist?“) und antwortet: an-nadschm ath-thāqib."},
 {arab: "الثَّاقِب", tr: "ath-thāqib", wurzel: "th-q-b", erkl: "„Der Durchbohrende“ – thaqaba: durchbohren (ein Loch, thuqb). Der Stern, dessen Licht die Finsternis durchschlägt. Bild mit Doppelboden: Auch die Wahrheit ist thāqib – sie durchbohrt jede Dunkelheit der Lüge."},
 {arab: "حَافِظ", tr: "ḥāfiẓ", wurzel: "ḥ-f-ẓ", erkl: "Hüter/Bewahrer – dieselbe Wurzel wie kitāb ḥafīẓ (Lektion 34) und Ḥifẓ. Über JEDER Seele einer: bewahrend (Schutzengel) und verzeichnend (Schreiberengel). Der Vers ist Trost und Aufsicht in einem Atemzug – je nachdem, was du nachts tust."},
 {arab: "الصُّلْب وَالتَّرَائِب", tr: "aṣ-ṣulb wa-t-tarāʾib", wurzel: "ṣ-l-b / t-r-b", erkl: "Lende/Rückgrat und Brustbein – die Körperregion, aus der das „sich ergießende Wasser“ hervortritt (nach verbreiteter Deutung auf Mann und Frau verteilt). Der Koran spricht die Zuhörer auf ihre eigene, unbestreitbare Entstehung an."},
 {arab: "تُبْلَى السَّرَائِر", tr: "tublā s-sarāʾir", wurzel: "b-l-w / s-r-r", erkl: "„(Der Tag,) da die Geheimnisse geprüft werden“ (86:9) – sarīra: das Verborgene des Herzens, die geheimen Absichten und Taten. Balā: prüfen, offenlegen (vgl. ‚herausgeholt wird, was in den Brüsten ist', Lektion 14). Innenrevision als Gerichtsform."},
 {arab: "قَوْل فَصْل", tr: "qaul faṣl", wurzel: "f-ṣ-l", erkl: "„Ein entscheidendes Wort“ (86:13) – faṣl wie yaum al-faṣl (Lektion 33): Der Koran trennt Wahrheit von Lüge, „und er ist kein Scherz (hazl)“. Gegen jede Lesart, die ihn zur Folklore oder zum ‚Kulturgut' verharmlost: Er meint, was er sagt."},
 {arab: "رُوَيْدًا", tr: "ruwaidā", wurzel: "r-w-d", erkl: "„Ein wenig, sachte“ – die Verkleinerungsform von Gemach: „Gib ihnen ein WENIG Zeit.“ Der Diminutiv trägt die Botschaft: Die Frist der Gegner ist klein, auch wenn sie sich groß anfühlt. Daʿwa-Gelassenheit in einem einzigen Wort."}
],
tafsir: [
 {vers: "Verse 1–4", text: "„Beim Himmel und dem Nachtstern! Und was lässt dich wissen, was der Nachtstern ist? Der durchbohrend helle Stern. Es gibt keine Seele, über der nicht ein Hüter wäre.“ – Ibn Kathīr: Der Schwur verknüpft das sichtbare Wachen des Sterns über der Nacht mit dem unsichtbaren Wachen der Engel über jeder Seele – was du am Himmel siehst, geschieht analog über dir. As-Saʿdī: Für den Gläubigen ist 86:4 zuerst Geborgenheit (vgl. 13:11: Engel behüten ihn „aus Allahs Befehl“) und dann Disziplin: Derselbe Hüter, der dich bewahrt, bezeugt dich. Wer das verinnerlicht, braucht keine Angst vor Menschen und keine Heimlichkeit vor Allah."},
 {vers: "Verse 5–10", text: "„So schaue der Mensch, woraus er erschaffen wurde …“ – der Herkunfts-Blick als Heilmittel gegen Hochmut und Auferstehungszweifel zugleich. „Gewiss hat Er die Macht, ihn zurückzubringen (radschʿ), am Tag, da die Geheimnisse geprüft werden – dann hat er weder Kraft noch Helfer.“ Al-Qurṭubī: Die Sure wählt als Gerichtsinhalt ausgerechnet die sarāʾir – weil die Mekkaner ihre Pläne nachts und geheim schmiedeten (V. 15!): Das Gericht findet dort statt, wo sie sich sicher fühlten, im Verborgenen. Für die Tazkiya heißt das: Arbeite an deinem Verborgenen – es ist der Prüfungsstoff (vgl. die chabīr-Frage aus Lektion 14 und das ‚Verborgene fürchten' aus Lektion 34)."},
 {vers: "Verse 11–17", text: "Doppelschwur: „Beim Himmel mit der Wiederkehr (radschʿ – der immer wiederkehrende Regen) und der Erde mit dem Aufspalten (ṣadʿ – das Aufbrechen für die Saat; vgl. falaq, Lektion 20): Er (der Koran) ist wahrlich ein entscheidendes Wort und kein Scherz.“ – Die Schwurzeugen sind Kreisläufe der Verlässlichkeit: So sicher Regen wiederkehrt und Saat aufbricht, so ernst und tragfähig ist dieses Wort. Dann das Finale: „Sie schmieden eine List, und Ich schmiede eine List. So lass den Ungläubigen Zeit – lass ihnen sachte Zeit.“ Ibn Kathīr: Allahs kaid ist kein Trick, sondern die überlegene Lenkung, die die Pläne der Gegner in ihr Gegenteil verkehrt (die Verfolger von damals wurden die Generäle des Islam von morgen). Für den Gläubigen folgt daraus das Verbot der Panik und der Rachsucht: Deine Aufgabe ist Standhaftigkeit – die Fristverwaltung liegt bei Allah."}
],
ahadith: [
 {text: "„Für ihn (den Menschen) gibt es (Engel), die einander ablösen, vor ihm und hinter ihm – sie behüten ihn aus Allahs Befehl“ – die Sunna und 13:11 als Kommentar zu 86:4; dazu: „Euch begleiten (Engel), die sich nachts und tags abwechseln, und sie versammeln sich im Fadschr- und ʿAṣr-Gebet …“", quelle: "Sahih al-Buchari, Nr. 555; Sahih Muslim, Nr. 632"},
 {text: "„Bewahre Allah(s Gebote), so bewahrt Er dich; bewahre Allah, so findest du Ihn vor dir …“ – aus dem Ibn-ʿAbbās-Hadith: Wer Allahs ḥifẓ sucht, lebt den Vers 86:4 aktiv.", quelle: "Sunan at-Tirmidhī, Nr. 2516; sahih"},
 {text: "„Allah gewährt dem Ungerechten Aufschub – doch wenn Er ihn ergreift, lässt Er ihn nicht entkommen.“ Dann rezitierte der Prophet ﷺ: „So ist der Griff deines Herrn, wenn Er die Städte ergreift …“ (11:102) – das amhilhum-Prinzip.", quelle: "Sahih al-Buchari, Nr. 4686; Sahih Muslim, Nr. 2583"}
],
hanafi: null,
umsetzung: [
 "Nutze 86:4 als Nacht-Vers: Vor dem Schlafen einmal bewusst – „über meiner Seele ein Hüter“: Dank für die Bewahrung des Tages, Tauba für das, was der Hüter protokolliert hat. (Kombiniere mit dem Schlaf-Programm aus Lektion 20.)",
 "Pflege deine sarāʾir wie dein Äußeres: EINE verborgene gute Tat pro Woche fest einplanen (nächtliches Gebet, geheime Sadaqa, stilles Duʿā für jemanden) – der Prüfungstag prüft das Verborgene, also investiere dort.",
 "Wende ruwaidā auf deine Konflikte an: Wenn gegen dich intrigiert wird (Arbeit, Familie, Gemeinde) – keine Gegenintrige: Pflichten erfüllen, Unrecht dokumentieren wo nötig, und die Fristverwaltung Allah überlassen (Buchari 4686 als Beruhigungs-Hadith).",
 "Lies den Koran als qaul faṣl: Wähle einen Vers, den du bisher als ‚schöne Poesie' überlesen hast, und frage: Was ENTSCHEIDET er in meinem Leben? Kein Scherz heißt: Jeder Vers will Konsequenz."
]
}
];
